<script setup lang="ts">
import {getRequestError} from '~/utils/errors'
import type {AdminRoomRow} from '~/types/api'
definePageMeta({layout:'admin',middleware:'admin'})
useSeoMeta({title:'Room management · BARNALI',robots:'noindex,nofollow'})
const api=useApi();const {data,pending,error,refresh}=await useAsyncData('admin-rooms',()=>api.request<AdminRoomRow[]>('/admin/rooms'))
const showCreate=ref(false);const name=ref('');const description=ref('');const busy=ref('');const message=ref('');const actionError=ref('')
async function create(){busy.value='create';message.value='';actionError.value='';try{await api.request('/admin/rooms',{method:'POST',body:{name:name.value,description:description.value}});name.value='';description.value='';showCreate.value=false;message.value='Room created.';await refresh()}catch(e:unknown){actionError.value=getRequestError(e,'Room could not be created.')}finally{busy.value=''}}
async function toggle(room:AdminRoomRow){const active=!room.active;const reason=window.prompt(`${active?'Activate':'Deactivate'} ${room.name}. Enter a reason for the audit log:`);if(!reason?.trim())return;busy.value=room.id;message.value='';actionError.value='';try{await api.request(`/admin/rooms/${room.id}/active`,{method:'PATCH',body:{active}});message.value='Room status updated.';await refresh()}catch(e:unknown){actionError.value=getRequestError(e,'Room status could not be updated.')}finally{busy.value=''}}
</script>
<template>
 <div class="admin-heading"><div><span class="eyebrow">Communities</span><h1>Rooms</h1><p>Manage community spaces and their public availability.</p></div><button class="btn" type="button" @click="showCreate=!showCreate">{{showCreate?'Cancel':'Create room'}}</button></div>
 <p v-if="message" class="notice notice--success" role="status">{{message}}</p><p v-if="actionError" class="notice notice--error" role="alert">{{actionError}}</p>
 <form v-if="showCreate" class="surface room-create" @submit.prevent="create"><div class="form-field"><label for="room-name">Room name</label><input id="room-name" v-model="name" class="input" maxlength="120" required></div><div class="form-field"><label for="room-description">Description</label><textarea id="room-description" v-model="description" class="compose__input" maxlength="600" required></textarea></div><button class="btn" :disabled="busy==='create'">{{busy==='create'?'Creating…':'Create public room'}}</button><p class="muted">New rooms are public and active. The API generates a unique room URL.</p></form>
 <div v-if="pending&&!data" class="surface surface-pad" role="status">Loading rooms…</div><div v-else-if="error" class="notice notice--error" role="alert">{{getRequestError(error,'Rooms unavailable.')}} <button class="btn btn--outline btn--small" @click="refresh()">Retry</button></div><EmptyState v-else-if="!data?.length" title="No rooms created" description="Create the first community room to open public discussion spaces." />
 <div v-else class="surface table-wrap"><table class="data-table"><thead><tr><th>Room</th><th>Visibility</th><th>Members</th><th>Discussions</th><th>Created</th><th></th></tr></thead><tbody><tr v-for="room in data" :key="room.id"><td><strong>{{room.name}}</strong><br><span class="muted">{{room.slug}} · {{room.description}}</span></td><td>{{room.active?'Active':'Inactive'}} · {{room.publicRoom?'Public':'Private'}}</td><td>{{room.memberCount}}</td><td>{{room.discussionCount}}</td><td>{{new Date(room.createdAt).toLocaleDateString()}}</td><td><button class="btn btn--outline btn--small" :disabled="busy===room.id" @click="toggle(room)">{{room.active?'Deactivate':'Activate'}}</button></td></tr></tbody></table></div>
</template>
<style scoped>.room-create{display:grid;gap:13px;padding:18px;margin-bottom:16px}.room-create .btn{justify-self:start}.room-create p{margin:0}</style>
